mapper.insert:
INSERT INTO accounts (
	user_num, account_name, account_type,
	opening_balance, credit_limit, opening_date, is_default_yn
)
VALUES (
	#{userNum}, #{accountName}, #{accountType},
	#{openingBalance}, #{creditLimit}, #{openingDate}, #{isDefaultYn}
)

mapper.select:
SELECT 
FROM accounts a
WHERE a.account_num = #{accountNum}

SELECT COALESCE(SUM(), 0)
FROM accounts a
WHERE a.user_num = #{userNum}

SELECT COUNT(*)
FROM accounts
WHERE user_num = #{userNum}
  AND account_name = #{accountName}
  AND use_yn = 'Y'

  AND account_num != #{excludeAccountNum}
